#include <stdio.h>

/* teste do desafio conversor-de-unidades — counter_protocol (03-tdd 3.9.3).
   Fase VALOR: sem captura de stdout. O teste declara os prototipos das tres
   caixas do aluno e confere os valores devolvidos com checa_double. Todos os
   valores tem representacao binaria exata (metades e quartos), por isso a
   comparacao por igualdade e legitima (prova-c regra 12). */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
double metrosParaCentimetros(double metros);
double quilosParaGramas(double quilos);
double conversorDeUnidades(int opcao, double valor);

SM_TEST(a_opcao_1_converte_comprimento) {
    checa_double("2.5 metros em centimetros", conversorDeUnidades(1, 2.5), 250.0,
                 "a opcao 1 manda o valor para a caixa de comprimento");
}

SM_TEST(a_opcao_2_converte_massa) {
    checa_double("1.5 quilos em gramas", conversorDeUnidades(2, 1.5), 1500.0,
                 "a opcao 2 manda o mesmo valor para a caixa de massa");
}

SM_TEST(opcao_desconhecida_devolve_o_valor) {
    checa_double("opcao 9 nao converte", conversorDeUnidades(9, 7.25), 7.25,
                 "nenhum case casa com 9: a caixa devolve o valor como veio");
}

SM_TEST(as_caixas_de_conversao_sozinhas) {
    checa_double("meio metro em centimetros", metrosParaCentimetros(0.5), 50.0,
                 "a caixa de comprimento multiplica por 100");
    checa_double("um quarto de quilo em gramas", quilosParaGramas(0.25), 250.0,
                 "a caixa de massa multiplica por 1000");
}

